def transform(grid):
    h, w = len(grid), len(grid[0])

    # The horizontal divider after the first set of tiles has the most 5s.
    divider = max(range(h), key=lambda r: sum(value == 5 for value in grid[r]))
    n = divider
    starts = range(0, w - n + 1, n + 1)

    # Associate each source color with its recolored sprite.
    sprites = {}
    for start in starts:
        color = next(
            (grid[r][c] for r in range(n)
             for c in range(start, start + n)
             if grid[r][c] != 0),
            None
        )
        if color is None:
            continue

        center_col = start + n // 2
        target = next(
            (grid[r][center_col] for r in range(2 * n + 2, h)
             if grid[r][center_col] != 0),
            None
        )
        if target is None:
            continue

        mask = [
            (r, c)
            for r in range(n)
            for c in range(n)
            if grid[r][start + c] == color
        ]
        sprites[color] = (target, mask)

    out = [[0 for _ in range(n * n)] for _ in range(n * n)]

    # The lower tile row gives the positions for each sprite.
    for start in starts:
        for r in range(n):
            for c in range(n):
                color = grid[n + 1 + r][start + c]
                if color not in sprites:
                    continue

                target, mask = sprites[color]
                for dr, dc in mask:
                    out[r * n + dr][c * n + dc] = target

    return out
