def transform(grid):
    h, w = len(grid), len(grid[0])
    n = next(c for c, value in enumerate(grid[0]) if value == 5)
    starts = range(0, w - n + 1, n + 1)

    # Each top panel defines a sprite and its output color.
    sprites = {}
    marker_row = 2 * n + 3
    for start in starts:
        cells = [
            grid[r][start + c]
            for r in range(n)
            for c in range(n)
            if grid[r][start + c] not in (0, 5)
        ]
        if not cells:
            continue

        color = max(set(cells), key=cells.count)
        mask = [
            (r, c)
            for r in range(n)
            for c in range(n)
            if grid[r][start + c] == color
        ]
        target = grid[marker_row][start + n // 2]
        sprites[color] = (target, mask)

    out = [[0] * (n * n) for _ in range(n * n)]

    # The middle panels encode where each sprite should appear.
    for start in starts:
        for r in range(n):
            for c in range(n):
                color = grid[n + 1 + r][start + c]
                if color not in sprites:
                    continue

                target, mask = sprites[color]
                for dr, dc in mask:
                    out[r * n + dr][c * n + dc] = target

    return out
